// Stage 15 (A + B): grade 9 questions written for the MEB Türkiye Yüzyılı Maarif Modeli programs (2024-25 onwards).
// Source of themes and learning outcomes: the official grade 9 frame plans on tymm.meb.gov.tr.
// Written as context-based multiple-choice questions following the MEB question-writing guide
// ("Bağlam Temelli Çoktan Seçmeli Soru Yazım Kılavuzu"): a real-life context, distractors from common
// misconceptions, no "all/none of the above" options. Turkish in both languages (it is the Turkish curriculum).
// Not approved by MEB: the subject teachers of the school are reviewing these questions.
//
// In each question below the FIRST option is the correct one; the bank moves it to a different letter.
import type { QuizDifficulty, QuizSubject } from './quiz-question-bank';

export type Meb9Seed = {
  /** MEB learning outcome code, e.g. "MAT.9.1.1". */
  outcome: string;
  /** MEB theme name (shown as the quiz topic). */
  theme: string;
  difficulty: QuizDifficulty;
  prompt: string;
  /** The first option is the correct answer. */
  options: [string, string, string, string];
  explanation: string;
};

/** Theme of each learning-outcome group ("9.1" = first theme), from the official frame plans. */
