/** Türk Dili ve Edebiyatı: the program repeats the same skill outcomes (TDE2.2 = reading, building meaning…) in each theme. */
export const TDE9_THEMES = ['Sözün İnceliği', 'Anlam Arayışı', 'Anlamın Yapı Taşları', 'Dilin Zenginliği'] as const;

function q(
  outcome: string,
  difficulty: QuizDifficulty,
  prompt: string,
  options: [string, string, string, string],
  explanation: string,
): Meb9Seed {
  const [prefix, grade, unit] = outcome.split('.');
  const theme = MEB9_THEMES[prefix]?.[`${grade}.${unit}`];
  if (!theme) throw new Error(`Unknown MEB outcome ${outcome}`);
  return { outcome, theme, difficulty, prompt, options, explanation };
}

/** A Türk Dili ve Edebiyatı question: the theme is given, the outcome is a skill code such as "TDE2.2". */
function tde(
  theme: (typeof TDE9_THEMES)[number],
  outcome: string,
  difficulty: QuizDifficulty,
  prompt: string,
  options: [string, string, string, string],
  explanation: string,
): Meb9Seed {
  return { outcome, theme, difficulty, prompt, options, explanation };
}

